+		brainDir, err := brainDirForKey(opts.Env, repo.RepoKey)
+		if err != nil {
+			return err
+		}
+		unlock, err := acquireSemanticIndexLock(brainDir)
+		if err != nil {
+			result.Error = err.Error()
+			results = append(results, result)
+			continue
+		}
+		source, err := workspaceSemanticSource(brainDir)
+		if err != nil {
+			unlock()
+			result.Error = err.Error()
+			results = append(results, result)
